  await expect(
    cdpSession.send("Storage.setCookies", {
      browserContextId: "ctx-nonexistent",
      cookies: [{ name: "x", value: "y", domain: "ks.invalid", path: "/" }],
    }),
  ).rejects.toThrow(/browser context/i);
}, 120_000);

